import{_ as o,o as a,c,a3 as s}from"./chunks/framework.DdpBa4_E.js";const n=JSON.parse('{"title":"Workspace 篇 - workspace 技巧","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/17-Workspace-篇-workspace-技巧.md","filePath":"books/chrome-devtools/17-Workspace-篇-workspace-技巧.md","lastUpdated":1781445373000}'),t={name:"books/chrome-devtools/17-Workspace-篇-workspace-技巧.md"};function r(d,e,p,l,i,m){return a(),c("div",null,[...e[0]||(e[0]=[s('<h1 id="workspace-篇-workspace-技巧" tabindex="-1">Workspace 篇 - workspace 技巧 <a class="header-anchor" href="#workspace-篇-workspace-技巧" aria-label="Permalink to &quot;Workspace 篇 - workspace 技巧&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>我们总是习惯于先在 <code>IDE</code> 或者文本编辑器中修改代码，然后再进入 <code>Chorme</code> 中进行调试，那有没有想过直接就在 <code>Chrome</code> 中来修改我们的代码呢？ 对于这样的想法，<code>Chrome DevTools</code> 提供了哪些支持呢？</p><h2 id="_1-在-chrome-中修改你的文件" tabindex="-1">1. 在 <code>Chrome</code> 中修改你的文件 <a class="header-anchor" href="#_1-在-chrome-中修改你的文件" aria-label="Permalink to &quot;1. 在 `Chrome` 中修改你的文件&quot;">​</a></h2><p>有时在代码执行的位置也是最容易编辑代码的位置（对于前端来说也就是浏览器）。如果你把项目的文件夹直接拖到 <code>Source</code> 面板，<code>DevTools</code> 会将你做出的修改同步到系统的文件中。</p><p>这对于快速修复代码非常方便！（我真的认识一个喜欢以这种方式做大部分编码的开发者） <img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f5b37db4e23ac~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>等等，其实它可以更好...</p><h2 id="_2-workspace-支持即时同步样式" tabindex="-1">2. <code>Workspace</code> 支持即时同步样式 <a class="header-anchor" href="#_2-workspace-支持即时同步样式" aria-label="Permalink to &quot;2. `Workspace` 支持即时同步样式&quot;">​</a></h2><p>正如我们刚才所说，一旦设置好了 <code>DevTools workspace</code>，就可以在 <code>Sources</code> 面板中编辑 <code>HTML</code> 和 <code>JavaScript</code>（或者甚至是 <code>TypeScript</code>，如果你有<code>sourcemaps</code>）文件，按 <code>ctrl + s</code> 后它将被保存 在文件系统中。</p><p>但是在样式方面它提供了更好的支持。 因为即使你只是在 <em>“元素”</em> 面板的 <em>“样式”</em> 部分中编辑样式规则，它也会立即同步。 请注意，是立刻！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f5b37d2312b72~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p><strong>&quot;黑魔法!&quot;</strong></p><h2 id="_3-为新选择器选择目标位置" tabindex="-1">3. 为新选择器选择目标位置 <a class="header-anchor" href="#_3-为新选择器选择目标位置" aria-label="Permalink to &quot;3. 为新选择器选择目标位置&quot;">​</a></h2><p>如果要向现有选择器添加新样式，很容易：只需在 <code>“元素”</code> 面板的 <code>“样式”</code> 部分中找到该选择器，然后开始编写 <code>CSS</code>。 但如果还没有这样的选择器，则需要按下<code>New Style Rule</code> 按钮。</p><p>当你使用工作区时，新样式规则的默认定位为 - <code>“inspector-stylesheet：1”</code> 如果你不想规则在这个位置显示，只需按住 <code>New Style Rule</code> 按钮，就可以看到一个列出所有 <code>CSS</code> 文件的选项。选择目的地，新规则就会保存在那里！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/28/167f3538987666fb~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_4-workspace-允许-css-注入" tabindex="-1">4. <code>Workspace</code> 允许 <code>CSS</code> 注入 <a class="header-anchor" href="#_4-workspace-允许-css-注入" aria-label="Permalink to &quot;4. `Workspace` 允许 `CSS` 注入&quot;">​</a></h2><p>设置工作区后，浏览器中所做的更改不仅会持久的保存到文件系统中，而且，<code>CSS</code> 的更改保存在文件系统后，立即就被浏览器选中并显示在你的页面上。<strong>并不需要手动刷新。</strong></p><p>敲黑板：我们 <code>没有使用额外的工具</code> - 没有 <code>webpack</code> 的热更新模块或者其他东西 - 只有一个本地服务以及 <code>DevTools&#39; workspace</code> 而已。</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f5b37d2051cca~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',20)])])}const k=o(t,[["render",r]]);export{n as __pageData,k as default};
